Translate("frFR", "winterspring", {
	title = "Berceau-de-l'Hiver",
	sections = {
		{
			title = "Résumé",
			text = [=[Berceau-de-l'Hiver est le toit gelé du nord de {link:kalimdor}Kalimdor{/link}, un haut pays de champs de neige, de vallées de pins et de glace bleue qui s'étend au-delà des tunnels des {link:timbermaw-furbolgs}Grumegueules{/link}. Peu de terres au monde sont aussi froides, et peu sont aussi pleines de choses anciennes. Des ruines elfiques dorment sous les congères. Un lac garde sous sa glace les éclats d'une relique volée. Des dragons du vol bleu veillent depuis des grottes dans les collines. Pourtant, la neige n'est pas paisible. Les furbolgs {link:winterfall-furbolgs}Tombe-hiver{/link} sont devenus fous, les bêtes-hiboux de l'est sont devenues sauvages, et à l'extrême sud l'air se fait chaud et fétide là où des démons s'attardent encore.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit en quelle année les {link:night-elves}elfes de la nuit{/link} bâtirent pour la première fois dans ces vallées. Il est certain qu'ils le firent bien avant la {link:great-sundering}Fracture{/link}. Des Bien-nés vivaient au bord du lac {link:lake-kel-theril}Kel'Theril{/link}, et les ruines de leurs demeures s'y trouvent encore. Les elfes se souviennent aussi d'un haut fait de leur grande prêtresse. Selon le récit des éleveurs de sabres-d'hiver, il y a quelque quatre mille ans, {link:tyrande-whisperwind}Tyrande Whisperwind{/link} sauva la reine des sabres-de-givre de géants déchaînés, et les grands félins de Berceau-de-l'Hiver sont depuis les amis des elfes. Des séléniens, les druides disent seulement que ce sont des créatures d'{red:elune}Elune{/red}, chargées de garder ses lieux les plus sacrés, et il existe de tels lieux dans les collines de l'est.]=],
		},
		{
			title = "De nos jours",
			text = [=[Berceau-de-l'Hiver n'appartient à aucune nation. Les elfes de la nuit entretiennent un petit village à {link:starfall-village}Pluie-d'Etoiles{/link}, et les éleveurs de sabres-de-givre restent sur leur roc au nord. Le cœur du pays, pourtant, est {link:everlook}Long-guet{/link}, une ville gobeline du {link:steamwheedle-cartel}Cartel Gentepression{/link}, où l'{link:alliance}Alliance{/link} et la {link:horde}Horde{/link} commercent sous les yeux des cogneurs du Cartel et ne se posent pas de questions. Des érudits sont venus aux sources chaudes, des nains de la {link:explorers-league}Ligue des explorateurs{/link} fouillent parmi les ruines, et l'{link:argent-dawn}Aube d'argent{/link} entretient un émissaire en ville. Tous partagent les mêmes tourments. La {link:winterfall-furbolgs}tribu Tombe-hiver{/link}, jadis paisible, s'est mise à boire une eau-de-feu verte brassée avec la souillure de {link:felwood}Gangrebois{/link}, et elle attaque tous ceux qui s'approchent. Et dans la gorge du Sombre murmure, à la lisière sud du pays et sous les hauteurs du {link:mount-hyjal}mont Hyjal{/link}, des démons de la {link:burning-legion}Légion ardente{/link} demeurent encore, et l'on dit que leur présence réchauffe les sources elles-mêmes.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les gobelins de {link:everlook}Long-guet{/link}.{/b} Marchands, forgerons et aubergistes du {link:steamwheedle-cartel}Cartel Gentepression{/link}, gardés par les cogneurs de Long-guet.
• {b}Les elfes de la nuit de {link:starfall-village}Pluie-d'Etoiles{/link}.{/b} Une poignée d'elfes qui veillent sur les ruines de leurs ancêtres.
• {b}Les furbolgs {link:winterfall-furbolgs}Tombe-hiver{/link}.{/b} Jadis alliés des {link:timbermaw-furbolgs}Grumegueules{/link}, aujourd'hui fous et violents sous les ordres de leur grand chef.
• {b}{link:timbermaw-hold}Les Grumegueules{/link}.{/b} Les derniers furbolgs sains d'esprit du nord, qui tiennent les tunnels entre Berceau-de-l'Hiver et {link:felwood}Gangrebois{/link}.
• {b}Le vol draconique bleu.{/b} Ses dragons et ses draconiens gardent les grottes de {link:mazthoril}Mazthoril{/link}.
• {b}Les bêtes des neiges.{/b} Sabres-de-givre, ours à dents d'éclat, chimères du vent glacial, yétis des chardons de glace et bêtes-hiboux rendues folles.
• {b}Les géants Frostmaul.{/b} Des géants de glace vivante qui tiennent la vallée de la gorge du Blanc murmure.
• {b}Les démons.{/b} Les {link:lady-hederine}Hederine{/link} et leur maîtresse hantent la gorge du Sombre murmure.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les Bien-nés.{/b} Avant la {link:great-sundering}Fracture{/link}, les Bien-nés volèrent un cristal sacré et tentèrent d'en drainer le pouvoir au bord du lac {link:lake-kel-theril}Kel'Theril{/link}. La relique se brisa, et leurs esprits restent liés à ce lieu.
• {b}La reine des sabres-de-givre.{/b} {link:tyrande-whisperwind}Tyrande Whisperwind{/link} sauva la reine des sabres-de-givre des géants, et les sabres-de-givre se joignirent aux elfes de la nuit.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} La {link:burning-legion}Légion ardente{/link} vint au mont Hyjal. {link:archimonde}Archimonde{/link} tomba lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, mais des démons s'attardent encore dans la gorge du Sombre murmure, au pied nord de la montagne. Aucune chronique ne dit quand ils vinrent.
• {b}De nos jours.{/b} Le Cartel a fait de {link:everlook}Long-guet{/link} le seul foyer chaleureux du nord, et tous les tourments des neiges passent par ses portes.]=],
		},
		{
			title = "Légendes des neiges",
			text = [=[• Les clients de l'auberge de {link:everlook}Long-guet{/link} apprennent vite à s'asseoir bien loin du poêle.
• La sorcière-docteur troll de Long-guet affirme que chaque bête détient un pouvoir qu'elle appelle e'ko, et qu'avec le bon charme on peut le capturer.
• Un vieux médium vit seul dans les collines à l'est de Long-guet. Il parle avec les morts, et certains disent que les morts répondent.
• On dit que les géants du givre perdent des éclats de glace si clairs qu'ils reflètent le pouvoir comme un miroir reflète la lumière.]=],
		},
	},
})

Translate("frFR", "everlook", {
	title = "Long-guet",
	sections = {
		{
			title = "Résumé",
			text = [=[Long-guet est une ville gobeline fortifiée au cœur de {link:winterspring}Berceau-de-l'Hiver{/link}, et la seule vraie ville du nord gelé. Le {link:steamwheedle-cartel}Cartel Gentepression{/link} la gouverne, et sa loi est simple : maintenez la paix et payez votre dû. L'{link:alliance}Alliance{/link} et la {link:horde}Horde{/link} y arrivent toutes deux à dos de griffon et de coursier du vent, et toutes deux y sont bienvenues tant que dure leur argent. Les cogneurs de Long-guet maintiennent l'ordre aux portes. Dans les murs se trouvent une auberge, une banque, des forgerons et des marchands. Il y a aussi des gens plus étranges : une sorcière-docteur troll, une inventrice de yétis mécaniques, un forgeron de la {link:thorium-brotherhood}Confrérie du thorium{/link} et un émissaire de l'{link:argent-dawn}Aube d'argent{/link}.]=],
		},
	},
})

Translate("frFR", "starfall-village", {
	title = "Pluie-d'Etoiles",
	sections = {
		{
			title = "Résumé",
			text = [=[Pluie-d'Etoiles est un petit village des elfes de la nuit à l'ouest de {link:everlook}Long-guet{/link}. Ses habitants vivent dans un pavillon parmi les pins, et ils montent une garde tranquille sur les ruines de leurs ancêtres. {link:wynd-nightchaser}Wynd Nightchaser{/link} connaît mieux que quiconque ici les vieux récits du pays. Un {link:dwarves}nain{/link} de la {link:explorers-league}Ligue des explorateurs{/link} se repose au pavillon en tant qu'invité, ruminant le souvenir des séléniens qui ont saccagé son camp. Les voyageurs venus de {link:darnassus}Darnassus{/link} et de {link:felwood}Gangrebois{/link} passent d'abord par Pluie-d'Etoiles, car c'est la porte par laquelle les elfes découvrent les secrets de {link:winterspring}Berceau-de-l'Hiver{/link}.]=],
		},
	},
})

Translate("frFR", "frostfire-hot-springs", {
	title = "Sources de Givrefeu",
	aliases = { "Givrefeu" },
	sections = {
		{
			title = "Résumé",
			text = [=[À l'ouest de {link:winterspring}Berceau-de-l'Hiver{/link}, non loin des tunnels des {link:timbermaw-furbolgs}Grumegueules{/link}, des bassins chauds fument dans la neige. Ce sont les Sources de Givrefeu. Aucun volcan ne se trouve près d'elles, et l'érudite {link:donova-snowden}Donova Snowden{/link}, qui campe à leur bord, croit que leur chaleur vient de quelque chose de plus sombre, loin au sud. Les furbolgs {link:winterfall-furbolgs}Tombe-hiver{/link} gardent les plus grandes sources avec une fureur étrange. Ils ont appris que l'eau adoucit le poison de leur eau-de-feu verte, et ils ne laissent personne d'autre en approcher.]=],
		},
	},
})

Translate("frFR", "timbermaw-post", {
	title = "Poste des Grumegueules",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Poste des Grumegueules se trouve à la lisière ouest de {link:winterspring}Berceau-de-l'Hiver{/link}, là où les tunnels des {link:timbermaw-hold}Grumegueules{/link} débouchent sur la neige. Les furbolgs {link:timbermaw-furbolgs}Grumegueules{/link} montent ici la garde à l'entrée de leur repaire. Ils accordent le passage à ceux en qui ils ont confiance, et combattent les autres. Les Grumegueules regardent l'est avec tristesse. Les {link:winterfall-furbolgs}Tombe-hiver{/link} étaient jadis leurs alliés, et aujourd'hui les coursiers Tombe-hiver passent par ici en rapportant la corruption de {link:felwood}Gangrebois{/link}.]=],
		},
	},
})

Translate("frFR", "winterfall-village", {
	title = "Village Tombe-hiver",
	sections = {
		{
			title = "Résumé",
			text = [=[Le village {link:winterfall-furbolgs}Tombe-hiver{/link} est le foyer des furbolgs Tombe-hiver, dans les collines à l'est de {link:everlook}Long-guet{/link}. C'est un lieu de huttes et de totems, et de peur. C'est ici que le grand chef de la tribu donne ses ordres, et ici que les coursiers apportent de {link:felwood}Gangrebois{/link} les tonneaux d'eau-de-feu verte. Les furbolgs du village sont plus grands et plus féroces que ne l'étaient autrefois leurs semblables. Leurs chamans et leurs ursa attaquent tout ce qui s'approche, bête ou voyageur.]=],
		},
	},
})

Translate("frFR", "lake-kel-theril", {
	title = "Lac Kel'Theril",
	aliases = { "Kel'Theril", "Les ruines de Kel'Theril" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le lac Kel'Theril est un lac gelé au milieu de {link:winterspring}Berceau-de-l'Hiver{/link}. Sur ses rives s'étendent les ruines des Bien-nés. Il y a bien longtemps, avant la {link:great-sundering}Fracture{/link}, les Bien-nés de ce lieu volèrent une relique sacrée et tentèrent d'en drainer le pouvoir. La relique explosa, et ses morceaux sombrèrent sous la glace. Les Bien-nés furent maudits pour leur orgueil. Leurs esprits errent encore dans les ruines, affligés et hostiles, cherchant à jamais les éclats de ce qui les a perdus.]=],
		},
	},
})

Translate("frFR", "mazthoril", {
	title = "Mazthoril",
	sections = {
		{
			title = "Résumé",
			text = [=[Mazthoril est un réseau de grottes glacées dans les collines au sud du lac {link:lake-kel-theril}Kel'Theril{/link}. C'est un repaire du vol draconique bleu. Des draconiens bleus et des bêtes arcaniques gardent ses tunnels, et des runes de cobalt sont incrustées dans ses sols gelés. Ceux qui se tiennent sur une telle rune en portant un signe du vol sont élevés par un pouvoir arcanique jusqu'à une haute corniche. Là attend {link:haleh}Haleh{/link}, qui parle pour les dragons bleus dans le monde des mortels.]=],
		},
	},
})

Translate("frFR", "frostsaber-rock", {
	title = "Roc des Sabres-de-Givre",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Roc des Sabres-de-Givre est un grand repère dans les neiges du nord de {link:winterspring}Berceau-de-l'Hiver{/link}, où se rassemblent les sabres-de-givre sauvages. C'est le domaine de leur matriarche, {link:shy-rotam}Shy-Rotam{/link}, qui surgit avec fureur quand la viande des siens est déposée sur sa pierre. Au pied du roc, loin de tout village, {link:rivern-frostwind}Rivern Frostwind{/link} dresse des sabres-de-givre à porter des cavaliers. Les {link:winterfall-furbolgs}Tombe-hiver{/link} errent parfois jusqu'ici, et l'éleveur les verrait volontiers partir.]=],
		},
	},
})

Translate("frFR", "owl-wing-thicket", {
	title = "Fourré de l'Aile de la chouette",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Fourré de l'Aile de la chouette gravit une crête au sud-est de {link:winterspring}Berceau-de-l'Hiver{/link}. C'est le foyer des séléniens, et ils le gardent avec une fureur qui a fait fuir érudits et fouilleurs. Tout au sommet de la crête se dresse un ancien autel d'{red:elune}Elune{/red}. Son accès est scellé, et cinq torches doivent brûler dans les grottes avant qu'il ne s'ouvre. Les druides du {link:cenarion-circle}Cercle cénarien{/link} disent que les séléniens furent choisis pour garder de tels lieux saints, et qu'ils le font encore.]=],
		},
	},
})

Translate("frFR", "ice-thistle-hills", {
	title = "Collines des Chardons de glace",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Collines des Chardons de glace s'étendent au sud-est de {link:everlook}Long-guet{/link}. Les yétis des chardons de glace vivent dans des grottes parmi elles, et leurs patriarches et leurs matriarches portent de grandes cornes recourbées. Leur épaisse fourrure est prisée à Long-guet, où une inventrice {link:gnomes}gnome{/link} en eut besoin d'une grande quantité pour un secret à elle. Les collines sont froides même pour {link:winterspring}Berceau-de-l'Hiver{/link}, et les yétis ne les partagent pas de bon gré.]=],
		},
	},
})

Translate("frFR", "frostwhisper-gorge", {
	title = "Gorge du Blanc murmure",
	sections = {
		{
			title = "Résumé",
			text = [=[La gorge du Blanc murmure est une longue vallée au sud de {link:winterspring}Berceau-de-l'Hiver{/link}. Les géants Frostmaul y règnent, d'immenses créatures de glace vivante. Ce sont les mêmes géants qui menacèrent jadis la reine des sabres-de-givre, et ils ont fait de la vallée leur domaine. Des éclats de glace claire jonchent le canyon. Plus loin, parmi des ruines, un {link:satyrs}satyre{/link} nommé {link:lorax}Lorax{/link} fait les cent pas en marmonnant, ruminant un marché qui fut rompu.]=],
		},
	},
})

Translate("frFR", "darkwhisper-gorge", {
	title = "Gorge du Sombre murmure",
	sections = {
		{
			title = "Résumé",
			text = [=[La gorge du Sombre murmure se trouve à l'extrémité sud de {link:winterspring}Berceau-de-l'Hiver{/link}, sous les hauteurs du {link:mount-hyjal}mont Hyjal{/link}. Là, la neige cède la place à un air moite et à un ciel assombri. Des démons de la {link:burning-legion}Légion ardente{/link} demeurent dans la gorge, bien que la Légion ait été brisée à Hyjal. Les {link:lady-hederine}Hederine{/link} servent une maîtresse nommée dame Hederine. L'érudite {link:donova-snowden}Donova Snowden{/link} croit que la présence des démons est ce qui réchauffe les sources de Berceau-de-l'Hiver, loin au nord.]=],
		},
	},
})

Translate("frFR", "haleh", {
	title = "Haleh",
	subtitle = "Matrone protectrice du vol bleu",
	found = "Une haute corniche au-dessus des grottes de Mazthoril",
	hint = [=[Cherchez celle qui parle pour les dragons bleus, tout en haut des grottes de Mazthoril.]=],
	allegiance = "Vol draconique bleu",
	sections = {
		{
			title = "Résumé",
			text = [=[Haleh est une dragonne du vol bleu, les gardiens de la {link:arcane-magic}magie arcanique{/link}. Les siens l'appellent leur matrone protectrice. Elle demeure sur une haute corniche au-dessus des grottes de {link:mazthoril}Mazthoril{/link}, et seuls ceux qui se tiennent sur les runes de cobalt des grottes avec un signe de son vol peuvent l'atteindre. Elle est fière, froide et lente à accorder sa confiance, et elle parle rarement d'autre chose que des affaires de son vol.]=],
		},
		{
			title = "Importance",
			text = [=[Les Aspects ont ordonné aux vols draconiques de rester à l'écart des affaires des mortels. Haleh respecte cet ordre autant qu'elle le peut. Elle sait pourtant que le monde ne le permet pas toujours, surtout quand l'un des vols l'ignore avec mépris. Par elle, les dragons bleus prêtent leur pouvoir aux mortels contre la progéniture noire d'{link:deathwing}Aile-de-mort{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle veille sur {link:mazthoril}Mazthoril{/link}, le repaire du vol bleu.
• Elle reçoit l'écaille d'Awbee, une dragonne bleue cachée dans le pic {link:blackrock-mountain}Blackrock{/link}, et y lit ce qu'Awbee y a vu.
• Elle offre aux mortels le pouvoir du vol bleu contre la progéniture d'{link:deathwing}Aile-de-mort{/link}.
• Elle envoie ses élus auprès du Sculpteur {link:jeziba}Jeziba{/link}, à {link:ruins-of-andorhal}Andorhal{/link}, par son propre pouvoir arcanique.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune archive ne dit l'âge de Haleh, sa place parmi les dragons bleus, ni depuis combien de temps elle veille depuis {link:mazthoril}Mazthoril{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La matrone protectrice",
			hint = "Portez une écaille du vol bleu à Mazthoril.",
			text = [=[Depuis les profondeurs du pic {link:blackrock-mountain}Blackrock{/link}, Awbee envoya une écaille à sa matrone. Haleh y lut ce qu'Awbee avait vu et ressenti en ce lieu maudit : les enfants d'{link:deathwing}Aile-de-mort{/link} à l'œuvre. On ne pouvait le permettre. Puisque la montagne abrite Nefarian, le vol bleu ne pouvait le frapper lui-même. Il pouvait seulement donner du pouvoir à ceux qui le feraient.]=],
		},
		{
			title = "Le courroux du vol bleu",
			hint = "Acceptez le don du vol bleu.",
			text = [=[Haleh prévint que la route était pleine de périls et demanda un choix fait librement. À ceux qui acceptèrent, elle offrit le pouvoir de sa propre magie pour hâter leur route. Elle ouvrit le chemin vers les {link:eastern-plaguelands}Maleterres{/link} et les envoya à {link:jeziba}Jeziba{/link}, un mortel qu'elle disait aussi sage que les anciens.]=],
		},
		{
			title = "L'œil du dragon",
			hint = "Apportez au vol bleu un fragment de l'œil d'un dragon noir.",
			text = [=[Le fragment qu'on lui apporta de {link:stormwind-city}Stormwind{/link} la dégoûta aussitôt. C'était une écaille de la mère de la couvée noire, {link:onyxia}Onyxia{/link}, enchantée pour servir de clé à son repaire puis brisée. Haleh pouvait la reconstituer, mais seulement avec le sang d'un champion dragon noir : le général Drakkisath, qui commande les draconiens de Nefarian au pic {link:blackrock-mountain}Blackrock{/link}. Quand le sang arriva, elle forgea l'Amulette de Feu-drake. Grâce à elle, les protections d'Onyxia dans la {link:wyrmbog}Tourbière du Ver{/link}, au {link:dustwallow-marsh}marécage d'Âprefange{/link}, ne pouvaient plus barrer le chemin.]=],
		},
	},
	mentions = {
		{ text = "La matrone protectrice" },
		{ text = "Le courroux du vol bleu" },
		{ text = "Le courroux du vol bleu, vers {link:jeziba}Jeziba{/link}" },
		{ text = "L'œil du dragon" },
		{ text = "Amulette de Feu-drake" },
	},
	bonds = {
		{ id = "jeziba", name = "Jeziba", note = "elle lui envoie des héros" },
		{ id = "awbee", name = "Awbee", note = "une dragonne bleue qui la sert au pic Blackrock" },
	},
})

Translate("frFR", "donova-snowden", {
	title = "Donova Snowden",
	subtitle = "Érudite des sources chaudes",
	found = "Au bord des Sources de Givrefeu",
	hint = [=[Cherchez l'érudite qui campe au bord des sources chaudes de l'ouest.]=],
	allegiance = "Amie de Linken et de Krakle",
	aliases = { "Donova" },
	sections = {
		{
			title = "Résumé",
			text = [=[Donova Snowden vint à {link:winterspring}Berceau-de-l'Hiver{/link} pour percer le secret des {link:frostfire-hot-springs}Sources de Givrefeu{/link}, où l'eau chaude fume dans un pays sans volcans. Elle campe toujours à leur bord. Elle est patiente, curieuse et bienveillante, et elle croit que les terres froides recèlent plus de secrets qu'aucune terre chaude. Ses études l'ont menée à une affaire plus sombre qu'elle ne s'y attendait : la folie des {link:winterfall-furbolgs}Tombe-hiver{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Donova fut la première à remonter la folie des {link:winterfall-furbolgs}Tombe-hiver{/link} jusqu'à sa source. Grâce à ses travaux, on apprit que la tribu buvait une eau-de-feu tirée de la corruption de {link:felwood}Gangrebois{/link}, et que les sources chaudes elles-mêmes doivent peut-être leur chaleur à des démons.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle étudie les {link:frostfire-hot-springs}Sources de Givrefeu{/link} et leur eau étrange.
• Elle découvre que les {link:winterfall-furbolgs}Tombe-hiver{/link} se servent des sources pour purifier leur eau-de-feu.
• Elle trouve les démons de la gorge du Sombre murmure et les croit à l'origine de la chaleur des sources.
• Elle garde une épée pour son ami {link:linken}Linken{/link}, et sait comment elle peut être achevée.]=],
		},
		{
			title = "Non consigné",
			text = [=[Rien ne dit d'où vient Donova, ni quel ordre elle sert, si elle en sert un.]=],
		},
	},
	chapters = {
		{
			title = "L'eau-de-feu des Tombe-hiver",
			hint = [=[Apportez à l'érudite une fiole laissée tomber par les Tombe-hiver.]=],
			text = [=[La fiole était vide, à quelques gouttes près d'un liquide vert luminescent. Donova y reconnut aussitôt quelque chose de semblable à la boue de {link:felwood}Gangrebois{/link}. La piste menait aux camps de la tribu Deadwood, et de là aux horreurs toxiques du bois d'Arbrefer. Quand elle mélangea le poison à l'eau des sources, il perdit sa létalité mais garda son emprise sur ceux qui le buvaient. Elle comprit alors pourquoi les {link:winterfall-furbolgs}Tombe-hiver{/link} gardaient les sources : il leur en fallait l'eau pour fabriquer leur eau-de-feu.]=],
		},
		{
			title = "Le grand chef",
			hint = "Mettez fin à celui qui commande les Tombe-hiver.",
			text = [=[Les {link:winterfall-furbolgs}Tombe-hiver{/link} n'avaient jamais été une tribu violente, dit Donova. Seul leur chef avait pu les mettre sur cette voie. Elle n'espérait pas défaire ce qui avait été fait, mais elle croyait que sans leur chef ils ne sombreraient pas davantage. Le chef portait un journal écrit en signes si grossiers qu'elle ne put les lire. Elle l'envoya au sud à {link:kelek-skykeeper}Kelek Skykeeper{/link}, un druide qui connaît bien les furbolgs de {link:felwood}Gangrebois{/link}.]=],
		},
		{
			title = "La source des sources",
			hint = [=[Voyagez vers le sud, là où l'air s'épaissit et le ciel s'assombrit.]=],
			text = [=[Donova ne croyait pas que les sources étaient réchauffées par la seule terre. Elle envoya un voyageur à l'extrême sud de {link:winterspring}Berceau-de-l'Hiver{/link}, là où l'air devient moite et le ciel s'assombrit. Là s'étendait la gorge du Sombre murmure et ses démons. Donova surveille désormais les sources, guettant tout autre signe de leur influence.]=],
		},
	},
	mentions = {
		{
			text = [=[Des ennuis à {link:winterspring}Berceau-de-l'Hiver{/link} !, de la part de Meggi Peppinrocker]=],
		},
		{ text = "La menace des {link:winterfall-furbolgs}Tombe-hiver{/link}" },
		{
			text = [=[L'eau-de-feu des {link:winterfall-furbolgs}Tombe-hiver{/link}]=],
		},
		{ text = "La chute dans la corruption" },
		{ text = "Une substance mystérieuse" },
		{ text = "Horreurs toxiques" },
		{ text = "Les coursiers {link:winterfall-furbolgs}Tombe-hiver{/link}" },
		{ text = "Le grand chef {link:winterfall-furbolgs}Tombe-hiver{/link}" },
		{ text = "La dernière pièce" },
		{ text = "Paroles du Grand Chef" },
		{
			text = [=[Les nouvelles sources, de la part de {link:krakle}Krakle{/link}]=],
		},
		{ text = "Des sources étranges" },
		{ text = "C'est un secret pour tout le monde" },
		{ text = "L'élixir de Videre" },
		{ text = "Rendez-vous à la tombe" },
	},
	bonds = {
		{ id = "high-chief-winterfall", name = "Grand chef Tombe-hiver", note = "le chef qu'elle voulait arrêter" },
		{ id = "kelek-skykeeper", name = "Kelek Skykeeper", note = "lit pour elle le journal du chef" },
		{ id = "linken", name = "Linken", note = "son ami, qui a perdu la mémoire" },
		{ id = "krakle", name = "Krakle", note = "son ami d'Un'Goro" },
	},
})

Translate("frFR", "rivern-frostwind", {
	title = "Rivern Frostwind",
	subtitle = "Éleveur de sabres-d'hiver",
	found = "Au pied du Roc des Sabres-de-Givre, à l'extrême nord",
	hint = [=[Trouvez l'éleveur solitaire de grands félins à l'extrême nord des neiges.]=],
	allegiance = "Éleveurs de sabres-d'hiver",
	aliases = { "Rivern" },
	sections = {
		{
			title = "Résumé",
			text = [=[Rivern Frostwind dresse les sabres-de-givre de {link:winterspring}Berceau-de-l'Hiver{/link} à porter des cavaliers, avec pour seule compagnie un grand félin blanc nommé Glacier. Ce sont les plus sauvages de tous les sabres et les plus difficiles à dompter. Rivern n'en confie pas à n'importe qui. Un cavalier doit gagner la confiance de l'éleveur comme celle des félins. Rivern garde le vieux récit de la façon dont {link:tyrande-whisperwind}Tyrande Whisperwind{/link} sauva la reine des sabres-de-givre, et demande la loyauté en son nom.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Rivern nourrit les jeunes sabres de viande de chimère et d'ours.
• Rivern chasse les {link:winterfall-furbolgs}Tombe-hiver{/link} loin du {link:frostsaber-rock}Roc des Sabres-de-Givre{/link}.
• Rivern envoie les loyaux contre les géants Frostmaul, vieux ennemis des sabres-de-givre.]=],
		},
	},
	mentions = {
		{ text = "Provisions pour sabres-de-givre" },
		{ text = "Intrusion des {link:winterfall-furbolgs}Tombe-hiver{/link}" },
		{ text = "Géants déchaînés" },
	},
	bonds = {
		{ id = "shy-rotam", name = "Shy-Rotam", note = "la reine des sabres-de-givre" },
	},
})

Translate("frFR", "wynd-nightchaser", {
	title = "Wynd Nightchaser",
	subtitle = "Maître des traditions de Pluie-d'Etoiles",
	found = "Pluie-d'Etoiles",
	hint = [=[Parlez à l'elfe de Pluie-d'Etoiles qui connaît les vieux récits du pays.]=],
	allegiance = "Elfes de la nuit · Pluie-d'Etoiles",
	aliases = { "Wynd" },
	sections = {
		{
			title = "Résumé",
			text = [=[Wynd Nightchaser passe la plupart de ses jours à {link:starfall-village}Pluie-d'Etoiles{/link}, et peu de gens connaissent mieux que lui les ruines de {link:winterspring}Berceau-de-l'Hiver{/link}. Les érudits de {link:felwood}Gangrebois{/link} et de {link:darnassus}Darnassus{/link} lui envoient leurs élèves. Il raconte simplement l'histoire de {link:lake-kel-theril}Kel'Theril{/link} : un peuple maudit, lié au lieu de son rituel manqué.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il raconte l'histoire des Bien-nés qui volèrent une relique sacrée et la brisèrent sous le lac.
• Il envoie les curieux à {link:jaron-stoneshaper}Jaron Stoneshaper{/link}, qui a vu les ruines de ses propres yeux.
• Il envoie le cristal de {link:temple-of-zin-malor}Zin-Malor{/link} restauré à {link:darnassus}Darnassus{/link}, pour qu'il soit gardé loin de ceux qui en feraient mauvais usage.]=],
		},
	},
	chapters = {
		{
			title = "Le cristal rendu",
			hint = "Rapportez le cristal réparé à Berceau-de-l'Hiver.",
			text = [=[Le cristal ne pouvait jamais retourner à son temple, car le temple était en ruine. Wynd jugea que seuls quelques-uns des mages les plus puissants pouvaient le maîtriser, et qu'il revenait à ceux qui n'en abuseraient pas. Il l'envoya à l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link}.]=],
		},
	},
	mentions = {
		{ text = "En route pour {link:winterspring}Berceau-de-l'Hiver{/link} !" },
		{ text = "{link:starfall-village}Pluie-d'Etoiles{/link}" },
		{ text = "{link:lake-kel-theril}Les ruines de Kel'Theril{/link}" },
		{ text = "Les Bien-nés repentants" },
		{ text = "Le cristal de {link:temple-of-zin-malor}Zin-Malor{/link}" },
	},
	bonds = {
		{ id = "jaron-stoneshaper", name = "Jaron Stoneshaper", note = "un invité à Pluie-d'Etoiles" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "reçoit le cristal" },
	},
})

Translate("frFR", "jaron-stoneshaper", {
	title = "Jaron Stoneshaper",
	subtitle = "Fouilleur de la Ligue des explorateurs",
	found = "Le pavillon de Pluie-d'Etoiles",
	hint = [=[Trouvez le nain de la Ligue des explorateurs qui se repose à Pluie-d'Etoiles.]=],
