			text = [=[Jaron Stoneshaper est un {link:dwarves}nain{/link} de la {link:explorers-league}Ligue des explorateurs{/link} venu à {link:winterspring}Berceau-de-l'Hiver{/link} chercher ses reliques magiques. Il apprit vite que la plupart d'entre elles sont bien gardées. Des séléniens s'abattirent sur son camp de fouilles au sud, fracassèrent ses caisses et emportèrent une amulette qu'il venait de déterrer. Un de ses amis n'en réchappa pas. Jaron se repose désormais à {link:starfall-village}Pluie-d'Etoiles{/link}, meurtri mais pas découragé.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fouilla parmi les ruines du sud de {link:winterspring}Berceau-de-l'Hiver{/link} jusqu'à ce que les séléniens le chassent.
• Il se rendit au lac {link:lake-kel-theril}Kel'Theril{/link} et vit ses esprits affligés.
• Il envoya les éclats trouvés sous le lac à {link:aurora-skycaller}Aurora Skycaller{/link}, dans les {link:eastern-plaguelands}Maleterres{/link}.]=],
		},
	},
	mentions = {
		{ text = "Séléniens enragés" },
		{ text = "Séléniens enragés, l'amulette rendue" },
		{
			text = [=[Les esprits tourmentés de {link:lake-kel-theril}Kel'Theril{/link}]=],
		},
	},
	bonds = {
		{ id = "aurora-skycaller", name = "Aurora Skycaller", note = "reçoit les éclats" },
		{ id = "wynd-nightchaser", name = "Wynd Nightchaser", note = "son hôte à Pluie-d'Etoiles" },
	},
})

Translate("frFR", "umbranse-the-spiritspeaker", {
