	subtitle = "Médium des morts",
	found = "Une demeure isolée dans les collines à l'est de Long-guet",
	hint = [=[Cherchez le vieux médium qui vit seul dans les collines de l'est.]=],
	allegiance = "Allié du vol draconique vert",
	aliases = { "Umbranse" },
	sections = {
		{
			title = "Résumé",
			text = [=[Umbranse est un humain âgé qui vit en reclus dans l'est de {link:winterspring}Berceau-de-l'Hiver{/link}. C'est un médium qui parle pour les morts, et le dragon vert {link:itharius}Itharius{/link} le compte parmi les alliés mortels de son vol. Ses arts sont étranges même pour les savants. Un livre qu'il donna à l'{link:argent-dawn}Aube d'argent{/link} a laissé perplexes ses meilleurs érudits.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il accepte de prêter son art de parler aux morts pour atteindre le dragon rêveur Eranikus.
• Il a perdu son plus puissant instrument d'augure, qu'on lui a pris contre sa volonté.
• Il écrivit {i}Etudes sur la langue des Esprits{/i}, aujourd'hui entre les mains de l'{link:argent-dawn}Aube d'argent{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Selon les propres mots d'Eranikus",
			hint = "Venez auprès du médium à la demande d'un dragon vert.",
			text = [=[Eranikus n'est pas mort, dit Umbranse, pas au sens où les mortels l'entendent. Il promit néanmoins que le dragon donnerait un jour conseil de sa propre voix. Mais d'abord, il avait besoin de l'aide de quelqu'un de plus jeune et de plus fort, car son instrument d'augure avait été volé.]=],
		},
	},
	mentions = {
		{ text = "Selon les propres mots d'Eranikus" },
		{
			text = [=[{link:duke-nicholas-zverenhoff}Duc Nicholas Zverenhoff{/link}, en portant son livre]=],
		},
	},
	bonds = {
		{ id = "itharius", name = "Itharius", note = "le compte pour allié" },
		{ id = "gregor-greystone", name = "Gregor Greystone", note = "envoya son livre à l'Aube" },
	},
})

