Translate("frFR", "lorax", {
	title = "Lorax",
	subtitle = "Satyre de la forge démoniaque",
	found = "Des ruines au sud de la gorge du Blanc murmure",
	hint = [=[Cherchez le satyre qui fait les cent pas parmi les ruines au sud de la gorge.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Lorax est un {link:satyrs}satyre{/link} qui se tient parmi des ruines au sud de {link:winterspring}Berceau-de-l'Hiver{/link}. À l'en croire, ses jours tournent en un lent cercle de chagrin, de haine et d'intrigue. Il connaît l'art de la forge démoniaque. Il conclut jadis un marché pour l'enseigner à un {link:orcs}orc{/link} {link:blackrock-mountain}Blackrock{/link} nommé Goraluk Anvilcrack, en échange de son âme. Goraluk prit une cuirasse non forgée et s'enfuit au pic Blackrock sans payer.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il offre son savoir à quiconque ira recouvrer l'âme qu'on lui doit.
• Il remet une pique imprégnée de gangrène pour boire l'âme de Goraluk au moment de sa mort.]=],
		},
	},
	chapters = {
		{
			title = "Le marché rompu",
			hint = "Écoutez le récit du satyre, et réglez sa dette.",
			text = [=[Une âme, n'importe quelle âme, vaut quelque chose en ces temps, dit Lorax, même celle d'un {link:orcs}orc{/link} {link:blackrock-mountain}Blackrock{/link}. Quand la pique revint tachée de l'âme de Goraluk, avec la cuirasse volée, le {link:satyrs}satyre{/link} tint sa part du pacte.]=],
		},
	},
	mentions = {
