			hint = "Protégez Ranshalla pendant qu'elle monte jusqu'à l'autel.",
			text = [=[Ranshalla gravit la crête et alluma cinq torches dans les grottes, récitant en chemin les paroles de {link:lake-kel-theril}Kel'Theril{/link}. L'autel s'éveilla. Il montra que les séléniens n'étaient pas de simples bêtes. L'archidruide {link:fandral-staghelm}Fandral Staghelm{/link} dit plus tard que les druides le savaient depuis longtemps : les séléniens sont des créatures d'Elune, choisies pour garder ses lieux les plus sacrés.]=],
		},
	},
	mentions = {
