	bonds = {
		{ id = "erelas-ambersky", name = "Erelas Ambersky", note = "l'envoya à Berceau-de-l'Hiver" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "apprit ce qu'elle découvrit" },
	},
})

