Translate("frFR", "winterfall-furbolgs", {
	title = "Furbolgs Tombe-hiver",
	aliases = { "Tombe-hiver", "tribu Tombe-hiver" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Tombe-hiver sont la tribu {link:furbolgs}furbolg{/link} de {link:winterspring}Berceau-de-l'Hiver{/link}. Ce n'était pas un peuple violent, et ils furent longtemps les alliés des {link:timbermaw-furbolgs}Grumegueules{/link}. Cela a changé. Leur grand chef a exigé d'eux d'étranges choses, et ils s'abattent désormais sur quiconque s'approche, bête ou voyageur, elfe ou gobelin. Ils ont un village dans les collines à l'est de {link:everlook}Long-guet{/link} et des camps près des {link:frostfire-hot-springs}Sources de Givrefeu{/link}.]=],
		},
		{
			title = "L'eau-de-feu",
			text = [=[La folie a une source. Des coursiers de la tribu traversent les {link:timbermaw-furbolgs}Grumegueules{/link} jusqu'aux furbolgs Deadwood de {link:felwood}Gangrebois{/link}, eux-mêmes rendus fous par la corruption gangrenée. Ils en rapportent un breuvage vert tiré du poison des horreurs toxiques du bois d'Arbrefer. Seul, il les tuerait. Mêlé à l'eau des sources chaudes, il perd sa létalité mais garde son pouvoir, et ceux qui le boivent deviennent plus grands et plus sauvages. C'est pourquoi les Tombe-hiver gardent les sources avec tant de férocité. Les furbolgs portent encore des perles spirituelles pour éloigner les mauvais esprits, mais les perles ne les ont pas protégés de ce qu'ils sont devenus.]=],
		},
	},
})

Translate("frFR", "crystal-of-zin-malor", {
	title = "Cristal de Zin-Malor",
	sections = {
		{
			title = "Résumé",
			text = [=[Le cristal de Zin-Malor est une relique capable de contenir et de commander de grandes forces arcaniques. Seuls les vraiment dignes peuvent le maîtriser, et seule une poignée des mages les plus puissants pourraient l'espérer. Il porte le nom du {link:temple-of-zin-malor}Temple de Zin-Malor{/link}, qui gît aujourd'hui en ruine en {link:azshara}Azshara{/link}. Aux temps anciens, les Bien-nés de {link:lake-kel-theril}Kel'Theril{/link} le volèrent, voulant drainer son pouvoir pour eux-mêmes. Dans cette tentative, le cristal se brisa dans une grande explosion, et ses morceaux sombrèrent sous la glace du lac. Les Bien-nés furent maudits à rester là pour toujours, cherchant encore les fragments.]=],
		},
		{
			title = "Reconstitué",
			text = [=[De nos jours, la pioche d'un {link:dwarves}nain{/link} brisa la glace et remonta quatre fragments. La haute-elfe {link:aurora-skycaller}Aurora Skycaller{/link} les reconnut. Grâce aux écrits sacrés des Bien-nés, retrouvés dans le temple en ruine d'{link:azshara}Azshara{/link}, elle reconstitua le cristal. Il fut montré à un esprit de {link:lake-kel-theril}Kel'Theril{/link} qui se repentait de l'ancien crime, et cet esprit trouva la paix. Le cristal ne pouvait jamais retourner à son temple. {link:wynd-nightchaser}Wynd Nightchaser{/link}, de {link:starfall-village}Pluie-d'Etoiles{/link}, l'envoya à l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link}, à {link:darnassus}Darnassus{/link}, qui loua ceux qui l'avaient porté de ne pas avoir tenté de s'en servir eux-mêmes.]=],
		},
	},
})
